package com.flippingfriend.companion;
import com.flippingfriend.model.ItemFeatures;
/** Pure fail-closed binding of slot evidence to CandidateFactory unwind-loss inputs. */
final class BuyReplacementUnwindLossInputContextComposer {
 BuyReplacementUnwindLossInputContext compose(BuyReplacementExpectedSlotOccupancyEvaluationSet s,int currentLowPrice,ItemFeatures features,int bucketSeconds,long marketObservedAt,long at){if(s==null||features==null||features.getItemId()!=s.getItemId()||currentLowPrice<=0||bucketSeconds<=0||marketObservedAt>s.getEvaluatedAt()||marketObservedAt+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||!Double.isFinite(features.getVolatility())||features.getVolatility()<0)return null;for(BuyReplacementExpectedSlotOccupancyEvaluation e:s.getEvaluations())if(!valid(e,s))return null;return new BuyReplacementUnwindLossInputContext(s,currentLowPrice,features.getVolatility(),bucketSeconds,marketObservedAt,at);}
 private static boolean valid(BuyReplacementExpectedSlotOccupancyEvaluation e,BuyReplacementExpectedSlotOccupancyEvaluationSet s){return e!=null&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&e.getBuyPrice()>0&&e.getSellPrice()>0&&e.getTotalCost()==(long)e.getBuyPrice()*e.getExactRemainderQuantity()&&e.getTotalNetMargin()==e.getNetMarginPerItem()*e.getExactRemainderQuantity()&&Double.isFinite(e.getExpectedSlotHours())&&e.getExpectedSlotHours()>=1.0/60.0&&Double.compare(e.getCompletionProbability(),e.getBuyProbability()*e.getSellProbability())==0;}
}
